  return JSON.stringify(value);
}
const envelopes = [
  'environment_context',
  'permissions',
  'user_instructions',
  'apps_instructions',
  'skill',
  'stoa-profile',
  'local-command-caveat',
  'local-command-stdout',
  'system-reminder',
