}
function commandRemainder(rest: string, expectedNext?: string): string {
  if (
    rest.length &&
    !/^[\r\n]/u.test(rest) &&
    !(expectedNext && rest.startsWith(`<${expectedNext}>`))
  )
    refuse('ambiguous-runtime-context');
  return rest.replace(/^[\r\n]+/u, '');
}
