    'isApiErrorMessage',
    'isAbortedMidStream',
    'truncatedAfterOutput',
  ]) {
    if (record[flag] !== undefined && typeof record[flag] !== 'boolean')
      refuse('malformed-native-history');
    if (record[flag] === true) refuse('incomplete-source-turn', REMEDY);
