const CLAUDE_META = new Set([
  'file-history-snapshot',
  'progress',
  'summary',
  'custom-title',
  'last-prompt',
  'agent-name',
  'agent-color',
  'pr-link',
  'saved_hook_context',
  'system',
  'atis-latch',
  'cost-state',
  'mode',
]);
export async function decodeNativeHistory(
  provider: ImportProvider,
  records: Record<string, unknown>[],
  selectedId: string,
  selectedCwd: string,
  sourceFile: string,
  deadline: number,
): Promise<NativeHistory> {
