    let lastLifecycle:
      | {
          ordinal: number;
          outcome: 'pending' | 'success' | 'error' | 'cancelled';
        }
      | undefined;
    for (const [ordinal, record] of records.slice(1).entries()) {
      checkDeadline(deadline);
      const p = object(record.payload);
